mapper.select:
select ex.Ex_Name as exName, ex.Ex_Id_Type as exIdType, ex.Ex_Id_Number as exIdNumber, sec.Sec_Name as secName, pro.P_Name as pName, pro.P_Code as pCode, mn.* from Sec_Expert_Check mn left join Sec_Expert ex on ex.Ex_Id=mn.Ex_Id left join Pre_Project pro on pro.P_Id=mn.P_Id left join Sec_Info sec on mn.Sec_Id=sec.Sec_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.Sr_Id = #{params.srId}
and mn.State=#{params.state}
and INSTR(mn.Create_Uname,#{params.createUname})
and INSTR(sec.Sec_Name,#{params.secName})
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(pro.P_Code,#{params.pCode})
and INSTR(ex.Ex_Name,#{params.exName})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc

select pre_project.P_Name as pName, pre_project.p_Code as pCode, u.U_Name as createName, u1.U_Name as doUserName, sys_file.FileCreateUser as fileCreateId, sys_file.FileCreateUserName as fileCreateName, sys_file.FileFlowStatus as fileFlowStatusc, sys_file.T_Code as tCode, sec.sr_Id as secSrId, ssr.state_Time as stateTime, sec.*, ssr.sr_Id as srId, us.u_Id as extractUId, us.u_Name as extractUName from (select '待办' as taskType, Task_Return_Type as taskReturnType, TaskID as taskId, TaskID as ctTaskid, TaskName as taskName, TaskUser as doUserId, TaskSendTime as createtime, TaskEntityID as fileId, TaskEntityID as taskentityid, TaskSendUser as createId, TaskCurrentActID as actId from sys_task where 1=1
and TaskName like concat('%',#{params.taskName},'%')
UNION select '沟通' as taskType, '' as taskReturnType, CT_ID as taskId, CT_TaskID as ctTaskid, CT_Name as taskName, CT_User as doUserId, CT_Time as createtime, CT_FileID as fileId , CT_FileID as taskentityid, CT_SendUser as createId, CT_ActID as actId from sys_coordinationtask where 1=1
and CT_Name like concat('%',#{params.taskName},'%')
)t2 left join sys_file on t2.fileId = sys_file.FileID left join pre_project on sys_file.FileProject = pre_project.P_ID left join SYS_User u on u.U_ID=t2.createId left join SYS_User u1 on u1.U_ID=t2.doUserId left join Sec_Expert_Check sec on sys_file.FileId = sec.id left join Sec_Selection_Record ssr on ssr.Sr_Id = sec.sr_id left join sys_Task_Processin tp on tp.tp_entityid = ssr.Sr_Id left join sys_user us on tp.tp_user=us.U_ID left join SYS_FlowActivity act on act.ActID=tp.tp_actid where 1=1
and sys_file.t_Code = #{params.tCode}
and sys_file.FileFlowStatus <> 7 and ssr.state = 7 and sec.state <> 3
and tp.ActName = #{params.actName}
and act.ActType not like '%Gateway'
